def merge_summaries(parts: list) -> str:
    """
    把多段摘要聚合成整篇摘要。
    过滤空白段；去除内容重复的段（忽略空白和标点差异）；
    用换行连接剩余段。
    """
    def clean_summary(summary: str) -> str:
        """清理摘要，去除空白和标点，转换为小写"""
        import string
        return summary.strip().translate(str.maketrans('', '', string.punctuation)).lower()

    unique_summaries = set()
    cleaned_parts = [clean_summary(part) for part in parts if part.strip()]

    for cleaned_part in cleaned_parts:
        if cleaned_part not in unique_summaries:
            unique_summaries.add(cleaned_part)

    return '\n'.join(unique_summaries)

